// ═══ THROW in finally SWALLOWS try's exception ═══
public void dangerousMethod() {
    try {
        throw new RuntimeException("DATABASE CORRUPTION!");  // REAL error!
    } finally {
        throw new RuntimeException("Failed to close connection");  // SWALLOWS the real error!
    }
}
// Caller catches: "Failed to close connection"
// "DATABASE CORRUPTION!" is GONE! Not in stack trace. Not as cause. LOST.
// Developer debugging: "Why did the connection fail?" — wrong question!
// The REAL issue was database corruption — but nobody knows!

// ═══ RETURN in finally OVERRIDES try's return ═══
public int dangerousReturn() {
    try {
        return 100;  // try returns 100
    } finally {
        return 200;  // finally OVERRIDES → caller gets 200!
    }
}
// Caller: dangerousReturn() → 200 (NOT 100!)
// try's return value (100) is silently discarded.

// ═══ RETURN in finally SWALLOWS try's exception ═══
public String evenWorse() {
    try {
        throw new RuntimeException("CRITICAL ERROR!");
    } finally {
        return "everything is fine";  // SWALLOWS the exception!
    }
}
// Caller: evenWorse() → "everything is fine"
// "CRITICAL ERROR!" is GONE! Exception never reaches the caller!
// The method appears to succeed when it ACTUALLY FAILED!
