// ═══ CORRECT: catch exception in finally, DON'T re-throw ═══
public void safeCleanup() {
    Connection conn = null;
    try {
        conn = getConnection();
        executeTrade(conn);  // might throw
    } finally {
        if (conn != null) {
            try {
                conn.close();  // might throw — catch it HERE!
            } catch (SQLException closeEx) {
                log.warn("Failed to close connection", closeEx);
                // LOG it but DON'T re-throw — preserves try's exception!
            }
        }
    }
}

// ═══ BEST: try-with-resources handles this automatically ═══
public void bestPattern() throws SQLException {
    try (Connection conn = getConnection()) {
        executeTrade(conn);
    }
    // If both executeTrade AND conn.close() throw:
    // executeTrade's exception = PRIMARY (propagated to caller)
    // conn.close()'s exception = SUPPRESSED (attached via addSuppressed)
    // BOTH are visible in the stack trace! Nothing lost!
}

// Access suppressed exceptions:
try {
    bestPattern();
} catch (SQLException e) {
    System.out.println("Primary: " + e.getMessage());
    for (Throwable suppressed : e.getSuppressed()) {
        System.out.println("Suppressed: " + suppressed.getMessage());
    }
}
