package com.bank.danger.service;

public class DangerousFinallyService {

    // ═══ DANGEROUS: throw in finally swallows try's exception ═══
    public void throwInFinally() {
        try {
            throw new RuntimeException("SETTLEMENT_FAILED: bad exchange rate");
        } finally {
            throw new RuntimeException("LOCK_RELEASE_FAILED");
            // ↑ SWALLOWS "SETTLEMENT_FAILED"! Caller only sees "LOCK_RELEASE_FAILED"!
        }
    }

    // ═══ DANGEROUS: return in finally overrides try ═══
    public int returnInFinally() {
        try {
            return 100;
        } finally {
            return 200;  // OVERRIDES! Caller gets 200.
        }
    }

    // ═══ DANGEROUS: return in finally swallows exception ═══
    public String returnSwallowsException() {
        try {
            throw new RuntimeException("CRITICAL: data corruption!");
        } finally {
            return "OK";  // SWALLOWS exception! Caller sees "OK" — thinks everything is fine!
        }
    }

    // ═══ SAFE: catch in finally, log, don't re-throw ═══
    public void safeFinally() {
        try {
            throw new RuntimeException("REAL ERROR");
        } finally {
            try {
                cleanup();  // might throw
            } catch (Exception cleanupEx) {
                System.err.println("Cleanup failed (logged, not re-thrown): " + cleanupEx.getMessage());
                // DON'T re-throw! Preserves "REAL ERROR" for the caller.
            }
        }
    }

    private void cleanup() {
        throw new RuntimeException("cleanup failure");
    }
}
