// ─── File: src/test/java/com/bank/danger/FinallyDangerTest.java ───
package com.bank.danger;

import com.bank.danger.service.DangerousFinallyService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class FinallyDangerTest {

    DangerousFinallyService service = new DangerousFinallyService();

    @Test
    void throwInFinally_swallowsTryException() {
        assertThatThrownBy(() -> service.throwInFinally())
            .isInstanceOf(RuntimeException.class)
            .hasMessage("LOCK_RELEASE_FAILED");  // caller sees THIS
            // "SETTLEMENT_FAILED: bad exchange rate" is GONE! LOST!
        // The real error (settlement) is invisible. Developer debugs lock issue instead.
    }

    @Test
    void returnInFinally_overridesTryReturn() {
        assertThat(service.returnInFinally()).isEqualTo(200);  // NOT 100!
    }

    @Test
    void returnInFinally_swallowsException() {
        assertThat(service.returnSwallowsException()).isEqualTo("OK");
        // "CRITICAL: data corruption!" SWALLOWED! Method appears to succeed!
    }

    @Test
    void safeFinally_preservesRealException() {
        assertThatThrownBy(() -> service.safeFinally())
            .isInstanceOf(RuntimeException.class)
            .hasMessage("REAL ERROR");  // (Recommended) REAL error preserved!
        // Cleanup failure was LOGGED but not re-thrown.
    }

    @Test
    void tryWithResources_handlesBothExceptions() throws Exception {
        // try-with-resources: both exceptions VISIBLE!
        try {
            try (AutoCloseable resource = () -> { throw new Exception("CLOSE_FAILED"); }) {
                throw new RuntimeException("MAIN_ERROR");
            }
        } catch (RuntimeException e) {
            assertThat(e.getMessage()).isEqualTo("MAIN_ERROR");      // primary
            assertThat(e.getSuppressed()).hasSize(1);                  // suppressed
            assertThat(e.getSuppressed()[0].getMessage()).isEqualTo("CLOSE_FAILED");
            // BOTH visible! Nothing lost! try-with-resources is superior.
        }
    }
}
